import threading

class Work(object):

    def __init__(self):
        self.num = 0
        self.lock = threading.Lock()

    def increment(self):
        with self.lock:
            self.num += 1

work = Work()

def do_work():
    while True:
        work.increment()

threads = [threading.Thread(target=do_work) for _ in range(10)]

for thread in threads:
    thread.start()

for thread in threads:
    thread.join()

