def calculate_tax(income):
    if income <= 18200:
        return 0
    elif income <= 37000:
        return .19 * (income - 18200)
    elif income <= 87000:
        return .325 * (income - 37000) + 3572
    else:
        return .37 * (income - 87000) + 19822

