def find_prime_factors(n):
    i = 2
    factors = set()
    while i * i <= n:
        while (n % i) == 0:
            factors.add(i)
            n //= i
        i += 1
    if n > 1:
        factors.add(n)
    return factors

def find_rich_numbers(n):
    rich_numbers = []
    for i in range(1, n+1):
        factors = find_prime_factors(i)
        if len(factors) > 2:
            rich_numbers.append(i)
    return rich_numbers

