def pqsort(arr):
    if len(arr) < 2:
        return arr

    pivot = arr[0]

    lh = [x for x in arr[1:] if x < pivot]
    le = [x for x in arr[1:] if x == pivot]
    rh = [x for x in arr[1:] if x > pivot]

    return pqsort(lh) + [pivot] + le + pqsort(rh)

data = [3, 6, 8, 10, 1, 2, 1]
pqsort(data)

