import datetime

def get_birth_year(name):
    """
    Returns the birth year of the given historical figure.
    """
    if name == 'Napoleon':
        return 1769
    elif name == 'Julius Caesar':
        return 100
    elif name == 'Cleopatra':
        return 69
    else:
        raise Exception(f'Figure {name} not found')


def is_birth_year_in_future(figures):
    for figure in figures:
        year = get_birth_year(figure)
        if year > datetime.datetime.now().year:
            return True
    return False


print(is_birth_year_in_future(['Napoleon', 'Julius Caesar', 'Cleopatra']))

